```javascript
// Function to generate a random image URL
function getRandomImage() {
  const images = [
    'https://via.placeholder.com/600x400?text=Image1',
    'https://via.placeholder.com/800x600?text=Image2',
    'https://via.placeholder.com/1000x800?text=Image3',
    'https://via.placeholder.com/1200x1000?text=Image4',
    'https://via.placeholder.com/1600x1200?text=Image5'
